solution:
def count_runs(nums: list[int], k: int) -> int:
    counts = {0: 1}
    prefix = total = 0
    for x in nums:
        prefix += x
        total += counts.get(prefix - k, 0)
        counts[prefix] = counts.get(prefix, 0) + 1
    return total

perf.naive:
def count_runs(nums: list[int], k: int) -> int:
    total = 0
    for i in range(len(nums)):
        s = 0
        for j in range(i, len(nums)):
            s += nums[j]
            if s == k:
                total += 1
    return total
